function InitializeMainTrip() {
  const { selectedTripId, setSelectedTripId } = useTripStore();
  const { data: trips = [] } = useGetTrips();

  useEffect(() => {
    // 기본 선택은 한 번만 정한다. 재조회와 네트워크 복구는 사용자 선택을 바꾸지 않는다.
    if (selectedTripId === null && trips.length > 0) {
      setSelectedTripId((selectMainTrip(trips) ?? trips[0]).id);
    }
  }, [trips, selectedTripId, setSelectedTripId]);

  return null;
}

function OfflineMapCleanupTrigger() {
